```javascript
const fs = require('fs');

const [n, ...costs] = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
costs.sort((a, b) => a - b);

let candies = n;
let evolved = 0;

for (const cost of costs) {
  if (candies < cost) break;
  candies -= cost;
  evolved++;
}

console.log(evolved);
